files.agent-pane/theme.css:
/* Broadsheet's chat: voices, not boxes. Your prompt is a faint wash of the ink with a 2 px corner
   (a marked passage, not a bubble); tool output, edits and plans sit inside a hairline with no
   fill, so the page stays one sheet; secondary ink is the second and third steps of a fixed
   ladder (the ink at 72% and 66%; tool rows measure 4.54:1 in Light and 5.55:1 in Dark); links are
   the theme's accent ink; a long code line fades at the edge in place of a hard cut.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own (--agent-text, --agent-accent), so it reads over Broadsheet, Broadsheet Dark and a
   theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 5%, transparent);
  --cv-user-bubble-edge: transparent;
  --cv-user-bubble-radius: 2px;
  --cv-card-fill: transparent;
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 12%, transparent);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 66%, transparent);
  --cv-link: var(--agent-accent);
  --agent-link: var(--agent-accent);
  --cv-code-edge-fade: 24px;
}

files.markdown/theme.css:
/* Broadsheet's Markdown viewer: the chat's hand. Headings over a hairline, code on a faint wash
   with a 2 px corner, quotes behind a one-pixel rule, tables in hairlines with a plain header.
   Only --cmux-md-* properties on :root, every color mixed from the page's own, so this one file
   reads over the light and the dark theme file alike. */
:root {
  --cmux-md-muted-color: color-mix(in srgb, var(--cmux-md-text-color) 72%, transparent);
  --cmux-md-heading-weight: 600;
  --cmux-md-heading-rule: 1px solid color-mix(in srgb, var(--cmux-md-text-color) 12%, transparent);
  --cmux-md-code-background: color-mix(in srgb, var(--cmux-md-text-color) 5%, transparent);
  --cmux-md-code-radius: 2px;
  --cmux-md-border-color: color-mix(in srgb, var(--cmux-md-text-color) 12%, transparent);
  --cmux-md-quote-border: 1px solid color-mix(in srgb, var(--cmux-md-text-color) 28%, transparent);
  --cmux-md-quote-color: color-mix(in srgb, var(--cmux-md-text-color) 72%, transparent);
  --cmux-md-table-border: 1px solid color-mix(in srgb, var(--cmux-md-text-color) 12%, transparent);
  --cmux-md-table-header-background: transparent;
}
